import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import {createRecoveryDueHandler} from "../_shared/recovery-due-handler.mjs";
// Candidate only. Deploy with verify_jwt=true; no API for caller-supplied scope.
Deno.serve(createRecoveryDueHandler({env:(name:string)=>Deno.env.get(name),
 log:(tag:string,summary:string)=>console.info(tag,summary)}));

import {createRecoveryServerClient} from './recovery-server-client.mjs';
import {reevaluateDueRecovery} from './recovery-due.mjs';
import {verifySchedulerRequest} from './recovery-scheduler-auth.mjs';
// Candidate auth cut only. Gateway verify_jwt stays TRUE; HMAC is mandatory too.
// Public gateway key is not caller authorization; no service-key bearer bypass.
/** @param {{env:(name:string)=>string|undefined,makeClient?:any,evaluate?:any,log?:(tag:string,summary:string)=>void,now?:()=>number}} options */
export function createRecoveryDueHandler({env,makeClient=createRecoveryServerClient,evaluate=reevaluateDueRecovery,log=()=>{},now=()=>Date.now()}){
 return async(req)=>{
  if(req.method!=='POST')return new Response('method_not_allowed',{status:405});
  if(env('CRM_RECOVERY_AUTH_MODE')!=='scheduler_hmac_v1')return new Response('unavailable',{status:503});
  const verified=await verifySchedulerRequest(req,{projectUrl:env('SUPABASE_URL'),
   gatewayKey:env('CRM_RECOVERY_PUBLIC_GATEWAY_KEY'),secret:env('CRM_RECOVERY_SCHEDULER_SECRET'),now:now()});
  if(!verified.ok)return new Response('unauthorized',{status:401});
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);
  try{
   const key=env('SUPABASE_SERVICE_ROLE_KEY')??'';
   const client=makeClient(env('SUPABASE_URL')??'',key,{signal:controller.signal,allowDueRpc:true});
   const consumed=await client.rpc('crm_recovery_consume_scheduler_nonce',{
    p_nonce:verified.nonce,p_signed_at:verified.signedAt,p_tick:verified.tick});
   if(consumed.error)return new Response('unavailable',{status:503});
   if(consumed.data!==true)return new Response('replay_rejected',{status:409});
   const enabled=env('CRM_RECOVERY_DUE_ENABLED')==='true' && env('CRM_RECOVERY_SHADOW_ENABLED')==='true';
   if(!enabled)return Response.json({mode:'shadow',send_authorized:false,state:'disabled'});
   const result=await evaluate(client,{enabled,
    retentionReady:env('CRM_RECOVERY_RETENTION_READY')==='true',
    authorizedPhones:(env('CRM_RECOVERY_AUTHORIZED_PHONES')??'').split(',').map(p=>p.trim()).filter(Boolean),
    rollout:{channel_identity_verified:true,channel_verified_since:env('CRM_RECOVERY_CHANNEL_VERIFIED_SINCE'),purchase_coverage_verified:false}});
   log('recovery_due',JSON.stringify(result));
   return Response.json(result,{status:result.failed>0||['claim_failed','retention_failed'].includes(result.state)?503:200});
  }catch{return Response.json({mode:'shadow',send_authorized:false,state:'unavailable'},{status:503});}
  finally{clearTimeout(timer);controller.abort();}
 };
}

// Minimal server-only PostgREST adapter: SELECT and the three private RPCs only.
// Reuses native fetch like the existing webhook; no additional runtime SDK.
const tables=new Set(['crm_customers','crm_conversations','crm_whatsapp_message_events',
  'crm_tintim_message_events','tintim_order_links','orders','menu_availability',
  'store_settings','crm_follow_ups','tintim_conversations','crm_automation_settings']);
const rpcs=new Set(['crm_recovery_store_observation','crm_recovery_read_observations','crm_recovery_purge_expired','crm_recovery_permission_evidence','public_crocante_inventory']);
const dueRpcs=new Set(['crm_recovery_claim_due','crm_recovery_finish_due','crm_recovery_read_due','crm_recovery_consume_scheduler_nonce']);
const atom=value=>{const s=String(value);if(!/^[A-Za-z0-9_.:+-]+$/.test(s))throw Error('invalid_filter');return s;};
/** @param {string} url @param {string} key @param {{fetchImpl?:typeof fetch,signal?:AbortSignal,allowDueRpc?:boolean}} options */
export function createRecoveryServerClient(url,key,{fetchImpl=fetch,signal,allowDueRpc=false}={}) {
  const origin=new URL(url);
  if(origin.protocol!=='https:' || origin.username || origin.password || origin.search || origin.hash || !key)
    throw Error('server_configuration_invalid');
  const request=async(path,params,body)=>{
    try{
      const target=new URL('/rest/v1/'+path,origin);target.search=params.toString();
      const r=await fetchImpl(target.href,{method:body===undefined?'GET':'POST',signal,redirect:'error',
        headers:{apikey:key,Authorization:'Bearer '+key,'Content-Type':'application/json',Prefer:'count=exact'},
        ...(body===undefined?{}:{body:JSON.stringify(body)})});
      if(!r.ok)return {data:null,error:{code:'source_http_failed'}};
      const data=await r.json();
      const total=r.headers.get('content-range')?.split('/').at(-1);
      return {data,count:total && /^\d+$/.test(total)?Number(total):null,error:null};
    }catch{return {data:null,error:{code:'source_request_failed'}};}
  };
  return {
    from(table){
      if(!tables.has(table))throw Error('table_not_allowed');
      const params=new URLSearchParams();
      const q={select(columns){if(!/^[a-z_][a-z0-9_]*(?:,[a-z_][a-z0-9_]*)*$/.test(columns))throw Error('columns_invalid');params.set('select',columns);return q;},
        eq(k,v){params.append(atom(k),'eq.'+atom(v));return q;},
        in(k,values){params.append(atom(k),'in.('+values.map(atom).join(',')+')');return q;},
        gte(k,v){params.append(atom(k),'gte.'+atom(v));return q;},
        lte(k,v){params.append(atom(k),'lte.'+atom(v));return q;},
        order(k,{ascending=true}={}){params.set('order',atom(k)+(ascending?'.asc':'.desc'));return q;},
        range(a,b){if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||b<a)throw Error('range_invalid');params.set('offset',String(a));params.set('limit',String(b-a+1));return q;},
        limit(n){return q.range(0,n-1);},
        then(resolve,reject){return request(table,params).then(resolve,reject);}};
      return q;
    },
    rpc(name,args={}){if(!rpcs.has(name) && !(allowDueRpc && dueRpcs.has(name)))throw Error('rpc_not_allowed');return request('rpc/'+name,new URLSearchParams(),args);},
  };
}

import {assembleRecoveryEvaluation} from './recovery-snapshot.mjs';
import {privateRecoveryObservations} from './recovery-observation-store.mjs';
// No route, no sends. DB leases/deduplication own scheduling; snapshots are reread.
/** @param {any} client
 * @param {{enabled?:boolean,retentionReady?:boolean,authorizedPhones?:string[],rollout?:any,clock?:()=>string}} options
 * @param {{evaluate?:any}} dependencies */
export async function reevaluateDueRecovery(client,{enabled=false,retentionReady=false,
 authorizedPhones=[],rollout={},clock=()=>new Date().toISOString()}={},
 {evaluate=assembleRecoveryEvaluation}={}) {
 const summary={mode:'shadow',send_authorized:false,claimed:0,recorded:0,stale:0,failed:0};
 if(!enabled || !retentionReady || authorizedPhones.length<1 || authorizedPhones.length>5 ||
   authorizedPhones.some(p=>!/^55[0-9]{10,11}$/.test(p)))return {...summary,state:'disabled_or_unscoped'};
 const purge=await client.rpc('crm_recovery_purge_expired');
 if(purge.error || !Number.isInteger(purge.data)||purge.data<0||purge.data>=1000)return {...summary,state:'retention_failed'};
 const claimed=await client.rpc('crm_recovery_claim_due',{p_authorized_phones:authorizedPhones});
 if(claimed.error || !Array.isArray(claimed.data)||claimed.data.length>5)return {...summary,state:'claim_failed'};
 for(const job of claimed.data){
  summary.claimed++;
  try {
   const decision=await evaluate(client,{conversationId:job.conversation_id,now:clock(),rollout,
    observationStore:privateRecoveryObservations(client)});
   const retry=decision.classification==='insufficient_evidence';
   // Only a bounded, closed projection is accepted by SQL. Never persist interest
   // text, arbitrary JSON, customer IDs/phones or the complete snapshot.
   const blockers=[...new Set((decision.blockers??[]).map(s=>typeof s==='string'?s.split(':')[0]:'invalid_decision'))];
   const r=await client.rpc('crm_recovery_finish_due',{p_follow_up_id:job.follow_up_id,
    p_lease_token:job.lease_token,p_revision:job.revision,p_classification:decision.classification,
    p_blockers:blockers,p_retry:retry});
   if(r.error){summary.failed++;continue;}
   if(r.data==='recorded')summary.recorded++;else if(r.data==='stale')summary.stale++;else summary.failed++;
  }catch{summary.failed++;} // Lease expires; no private exception logging.
 }
 return {...summary,state:'evaluated'};
}

// Server-only read model. No HTTP endpoint, writes, credentials or send capability.
import { evaluateRecoveryShadow } from './recovery-shadow.mjs';
import { normalizeSignedRecoveryWebhook } from './recovery-meta-observation.mjs';
import { recoveryPermission } from './recovery-permission.mjs';
import { classifyRecoveryInterest } from './recovery-interest.mjs';
import { recoveryAvailability } from './recovery-availability.mjs';
const classifyInterest=text=>classifyRecoveryInterest(text).intent==='interest';

const uuid = value => typeof value === 'string' && /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(value);
const phone = value => {
  const digits = String(value ?? '').replace(/[^0-9]/g,'');
  const normalized = [10,11].includes(digits.length) ? '55'+digits : digits;
  return /^55[1-9][0-9]{9,10}$/.test(normalized) ? normalized : null;
};
const failed = reason => ({mode:'shadow',send_authorized:false,classification:'insufficient_evidence',blockers:[reason]});

/** Fully page SELECTs, detect truncation, duplicate IDs and count drift. */
async function readRows(client,table,columns,filters,{pageSize,maxRows,idKey='id'}) {
  const rows = [], ids = new Set();
  let total = null;
  for (let offset=0;offset<maxRows;offset+=pageSize) {
    let query = client.from(table).select(columns,{count:'exact'});
    for (const [method,key,value] of filters) query = query[method](key,value);
    const response = await query.order(idKey,{ascending:true}).range(offset,Math.min(offset+pageSize,maxRows)-1);
    if (response.error || !Array.isArray(response.data) || !Number.isSafeInteger(response.count) ||
      response.count<0 || response.count>maxRows || total !== null && response.count !== total)
      throw new Error('incomplete_source');
    total = response.count;
    for (const row of response.data) {
      if (!row[idKey] || ids.has(row[idKey])) throw new Error('unstable_source');
      ids.add(row[idKey]);rows.push(row);
    }
    if (rows.length === total) return rows;
    if (response.data.length !== pageSize || rows.length>total) throw new Error('truncated_source');
  }
  throw new Error('source_limit');
}

/**
 * Call only from a trusted server with a scoped privileged Supabase client.
 * rollout flags are server configuration, NEVER request body or browser input.
 * No caller-supplied normalized event/permission/order facts are accepted.
 * Signed text remains in memory; only the redacted evaluation is returned.
 */
export async function assembleRecoveryEvaluation(client,{conversationId,now,
  signedWebhook=null,metaConfig=null,rollout={},pageSize=200,maxRows=2000,observationStore=null}={}) {
  if (!uuid(conversationId) || !Number.isFinite(Date.parse(now)) || !client?.from ||
    !Number.isInteger(pageSize) || pageSize<1 || pageSize>500 ||
    !Number.isInteger(maxRows) || maxRows<pageSize || maxRows>10000)
    return failed('snapshot_configuration_invalid');
  const limit = {pageSize,maxRows};
  const read = (table,columns,filters=[],idKey='id') => readRows(client,table,columns,filters,{...limit,idKey});
  try {
    const conversations = await read('crm_conversations',
      'id,customer_id,tintim_conversation_id,status,created_at,updated_at,last_inbound_at,last_outbound_at',
      [['eq','id',conversationId]]);
    if (conversations.length !== 1) return failed('conversation_unavailable');
    const c = conversations[0];
    if (!Number.isFinite(Date.parse(c.created_at))) return failed('conversation_time_invalid');
    const customers = await read('crm_customers',
      'id,phone_e164,consent_status,consent_evidence,consent_at,commercial_opt_out,updated_at',
      [['eq','id',c.customer_id]]);
    if (customers.length !== 1 || !phone(customers[0].phone_e164)) return failed('customer_identity_unavailable');
    const customer = customers[0], customerPhone = phone(customer.phone_e164), clock = Date.parse(now);
    // Bounded recent episode, not a claim of complete lifetime chat history.
    const since = new Date(Math.max(Date.parse(c.created_at),clock-24*3600000)).toISOString();
    const dates = [['gte','occurred_at',since],['lte','occurred_at',now]];
    const [official,tintim,links,recentOrders,availability,settings,followups,stages,automation,recentPaidOrders] = await Promise.all([
      read('crm_whatsapp_message_events','id,message_id,conversation_id,phone_e164,direction,occurred_at,received_at',
        [['eq','conversation_id',conversationId],...dates]),
      read('crm_tintim_message_events','id,fingerprint,conversation_id,phone_e164,direction,occurred_at,received_at,time_basis',
        [['eq','conversation_id',conversationId],...dates]),
      c.tintim_conversation_id ? read('tintim_order_links','id,order_uuid,conversation_id,status,created_at',
        [['eq','conversation_id',c.tintim_conversation_id],['gte','created_at',since],['lte','created_at',now]]) : Promise.resolve([]),
      read('orders','id,customer_phone,created_at,payment_status,order_status,paid_at',
        [['gte','created_at',since],['lte','created_at',now]]),
      read('menu_availability','id,item_key,status,updated_at'),
      read('store_settings','id,key,value,updated_at',[['eq','key','orders_open']]),
      read('crm_follow_ups','id,conversation_id,status,sent_at',
        [['eq','conversation_id',conversationId],['gte','sent_at',since],['lte','sent_at',now]]),
      read('tintim_conversations','id,phone_digits,stage_label,last_observed_at',
        [['in','phone_digits',[customerPhone,customerPhone.slice(2)]],['gte','last_observed_at',since],['lte','last_observed_at',now]]),
      read('crm_automation_settings','singleton,follow_up_minutes',[['eq','singleton',true]],'singleton'),
      read('orders','id,customer_phone,created_at,payment_status,order_status,paid_at',
        [['gte','paid_at',since],['lte','paid_at',now]]),
    ]);
    if (automation.length !== 1) return failed('automation_settings_unavailable');
    const sourceProblems = [];
    const events = official.map(e => ({id:e.message_id,conversation_key:conversationId,
      direction:e.direction === 'app_echo' ? 'business_outbound' : e.direction,
      occurred_at:e.occurred_at,received_at:e.received_at,time_basis:'provider_timestamp',
      verified:phone(e.phone_e164) === customerPhone,content_origin:'unsupported',text:null}));
    if (observationStore) {
      const saved = await observationStore.read(conversationId);
      for (const row of saved) {
        const e = events.find(e => e.verified && e.id === row.message_id && e.direction === 'inbound' &&
          Date.parse(e.occurred_at) === Date.parse(row.occurred_at));
        if (e) Object.assign(e,{content_origin:'private_semantic',semantic_interest:row.semantic});
      }
    }
    // Receipt-time Tintim is retained separately, never upgraded to provider time.
    for (const e of tintim) {
      if (e.time_basis !== 'provider_timestamp') continue;
      events.push({id:'tintim:'+e.fingerprint,conversation_key:conversationId,direction:e.direction,
        occurred_at:e.occurred_at,received_at:e.received_at,time_basis:e.time_basis,
        verified:phone(e.phone_e164) === customerPhone,content_origin:'unsupported',text:null});
    }
    if (signedWebhook) {
      const incoming = await normalizeSignedRecoveryWebhook(signedWebhook.raw,
        {...metaConfig,signature:signedWebhook.signature,receivedAt:now});
      if (!incoming.accepted) return failed('signed_observation_rejected');
      const expected = `${metaConfig.wabaId}:${metaConfig.phoneNumberId}:${customerPhone}`;
      let matchedIdentity = false;
      for (const e of incoming.events) {
        // Meta can batch several customers in one signed envelope. Scope strictly
        // to this episode; never persist another customer's semantic observation.
        if (e.conversation_key !== expected) continue;
        matchedIdentity = true;
        if (Date.parse(e.occurred_at)<Date.parse(since)) continue;
        const old = events.find(x => x.id === e.id && x.direction === e.direction);
        if (old && Date.parse(old.occurred_at) !== Date.parse(e.occurred_at)) return failed('message_identity_conflict');
        if (observationStore) await observationStore.capture(conversationId,{...e,conversation_key:conversationId});
        if (old) Object.assign(old,{content_origin:e.content_origin,text:e.text});
        else events.push({...e,conversation_key:conversationId});
      }
      if (!matchedIdentity) return failed('signed_observation_identity_mismatch');
    }
    // A newly observed interest starts a bounded episode. Older opaque history
    // cannot certify this episode, nor permanently contaminate its completeness.
    const interestStart=events.filter(e=>e.verified && e.direction==='inbound' &&
      (e.content_origin==='private_semantic'?e.semantic_interest?.intent==='interest':
       e.content_origin==='customer_text' && classifyInterest(e.text)))
      .map(e=>Date.parse(e.occurred_at)).sort((a,b)=>b-a)[0];
    const episodeStart=Number.isFinite(interestStart)?interestStart:Date.parse(since);
    const episodeEvents=events.filter(e=>Date.parse(e.occurred_at)>=episodeStart);
    if(episodeEvents.some(e=>e.direction==='inbound' && !['customer_text','private_semantic'].includes(e.content_origin)))
      sourceProblems.push('inbound_content_unverified');
    if(tintim.some(e=>e.time_basis!=='provider_timestamp' && Date.parse(e.received_at)>=episodeStart))
      sourceProblems.push('tintim_time_unverified');
    for (const [field,direction] of [['last_inbound_at','inbound'],['last_outbound_at','business_outbound']]) {
      const recorded = Date.parse(c[field]);
      const observed = Math.max(-Infinity,...events.filter(e => e.direction === direction && e.verified)
        .map(e => Date.parse(e.occurred_at)));
      if (Number.isFinite(recorded) && recorded>=Date.parse(since) && recorded>observed)
        sourceProblems.push('conversation_activity_not_covered');
    }
    const associatedIds = [...new Set(links.filter(l => ['candidate','confirmed'].includes(l.status)).map(l => l.order_uuid))];
    const associatedOrders = associatedIds.length ? await read('orders',
      'id,customer_phone,created_at,payment_status,order_status,paid_at',[['in','id',associatedIds]]) : [];
    if (associatedIds.some(id => !associatedOrders.some(o => o.id === id))) sourceProblems.push('linked_order_unavailable');
    const orders = new Map();
    for (const o of [...recentOrders,...recentPaidOrders,...associatedOrders]) {
      const inWindow = [o.created_at,o.paid_at].some(t=>Date.parse(t)>=Date.parse(since) && Date.parse(t)<=clock);
      const direct = inWindow && phone(o.customer_phone) === customerPhone;
      const linked = associatedIds.includes(o.id);
      if (direct || linked) orders.set(o.id,{conversation_key:conversationId,
        identity_basis:direct ? 'verified' : 'candidate',payment_status:o.payment_status,status:o.order_status});
    }
    // Unattributed orders cannot prove that this contact did not buy.
    if ([...recentOrders,...recentPaidOrders].some(o => !phone(o.customer_phone) && !associatedIds.includes(o.id)))
      sourceProblems.push('unattributed_orders_in_window');
    if (stages.some(t => ['comprou','convertido','vendido','venda realizada'].includes(String(t.stage_label).trim().toLowerCase())))
      orders.set('stage',{conversation_key:conversationId,identity_basis:'candidate',payment_status:'unknown'});
    // Recheck versions: optimistic consistency for a shadow-only read, not a send claim.
    const [currentC,currentU] = await Promise.all([
      read('crm_conversations','id,updated_at',[['eq','id',c.id]]),
      read('crm_customers','id,updated_at',[['eq','id',customer.id]]),
    ]);
    if (currentC[0]?.updated_at !== c.updated_at || currentU[0]?.updated_at !== customer.updated_at)
      return failed('snapshot_changed_during_read');
    if (!['in_progress','waiting_customer'].includes(c.status)) return failed('conversation_not_active');
    const lastSent = followups.filter(f => ['sent','sent_manually'].includes(f.status) && Number.isFinite(Date.parse(f.sent_at)))
      .sort((a,b) => Date.parse(b.sent_at)-Date.parse(a.sent_at))[0]?.sent_at ?? null;
    const permission=await recoveryPermission(client,customer,now);
    const storeOpen=settings.length===1 && typeof settings[0].value==='boolean'?settings[0].value:null;
    const result = evaluateRecoveryShadow({now,events,orders:[...orders.values()],
      follow_up_minutes:automation[0].follow_up_minutes,
      consent_verified:permission.verified,
      opt_out:customer.commercial_opt_out !== false,
      store_open:storeOpen,
      availability:await recoveryAvailability(client,availability),
      recovery_contacted_at:lastSent,
      history_complete:rollout.channel_identity_verified === true &&
        Number.isFinite(Date.parse(rollout.channel_verified_since)) &&
        Date.parse(rollout.channel_verified_since)<=episodeStart && !sourceProblems.some(p =>
        ['tintim_time_unverified','conversation_activity_not_covered','inbound_content_unverified'].includes(p)),
      order_check_complete:rollout.purchase_coverage_verified === true && !sourceProblems.some(p => p.includes('order')),
    });
    if (sourceProblems.length) {
      result.blockers = [...new Set([...result.blockers,...sourceProblems])];
      if (result.classification === 'shadow_candidate') result.classification = 'blocked';
    }
    return {...result,snapshot_scope:'recent_24h',permission_basis:permission.basis,
      commerce_checks:{site_orders_read:true,unattributed_orders:sourceProblems.includes('unattributed_orders_in_window'),
        external_purchase_coverage:rollout.purchase_coverage_verified===true,
        store_basis:'checkout_orders_open',store_open:storeOpen},
      source_counts:{official:official.length,tintim:tintim.length},
      consistency:'optimistic_shadow_only'};
  } catch {return failed('snapshot_source_unavailable_or_incomplete');}
}

import { classifyRecoveryInterest, RECOVERY_VERSION } from './recovery-interest.mjs';

// Trusted normalized observations only; callers must verify source identity/signature.
// This evaluator cannot authorize a send. No DB/network dependency or side effect.
export function evaluateRecoveryShadow({events=[],now,follow_up_minutes=45,
  orders=[],consent_verified=false,opt_out=false,store_open=null,availability={},recovery_contacted_at=null,
  order_check_complete=false,history_complete=false}={}) {
  const result = {version:RECOVERY_VERSION,mode:'shadow',send_authorized:false,
    classification:'insufficient_evidence',blockers:[],interest:null,due_at:null};
  const clock = Date.parse(now);
  if (!Number.isFinite(clock) || !Number.isInteger(follow_up_minutes) ||
    follow_up_minutes < 15 || follow_up_minutes > 2880)
    return {...result,blockers:['invalid_clock_or_delay']};
  const seen = new Map();
  const accepted = [];
  let invalid = false;
  for (const e of events) {
    const at = Date.parse(e.occurred_at);
    if (e.verified !== true || e.time_basis !== 'provider_timestamp' ||
      !['inbound','business_outbound'].includes(e.direction) || !e.id ||
      typeof e.conversation_key !== 'string' || !e.conversation_key ||
      !Number.isFinite(at) || at > clock || (e.received_at &&
        (!Number.isFinite(Date.parse(e.received_at)) || Date.parse(e.received_at) < at))) {
      invalid = true; continue;
    }
    const key = `${e.conversation_key}:${e.direction}:${e.id}`;
    const fingerprint = JSON.stringify([e.occurred_at,e.text,e.content_origin]);
    if (seen.has(key) && seen.get(key) !== fingerprint) invalid = true;
    if (!seen.has(key)) {seen.set(key,fingerprint);accepted.push({...e,at});}
  }
  if (invalid) result.blockers.push('unverified_or_invalid_event');
  if (!order_check_complete) result.blockers.push('order_check_incomplete');
  if (!history_complete) result.blockers.push('conversation_history_incomplete');
  if (new Set(accepted.map(e => e.conversation_key)).size !== 1)
    return {...result,blockers:[...result.blockers,'conversation_identity_unresolved']};
  accepted.sort((a,b) => a.at-b.at || a.id.localeCompare(b.id));
  const inbound = accepted.filter(e => e.direction === 'inbound');
  const outgoing = accepted.filter(e => e.direction === 'business_outbound');
  const lastIn = inbound.at(-1), lastOut = outgoing.at(-1);
  let declined = false, possiblePurchase = false;
  for (const e of inbound) {
    // Referral, forwarded content and quoted messages cannot confirm interest.
    if (!['customer_text','private_semantic'].includes(e.content_origin)) continue;
    const observation = e.content_origin === 'private_semantic' ? e.semantic_interest : classifyRecoveryInterest(e.text);
    if (!observation || observation.version !== RECOVERY_VERSION) continue;
    if (observation.intent === 'opt_out') opt_out = true;
    if (observation.intent === 'possible_purchase') possiblePurchase = true;
    if (observation.intent === 'declined') {declined = true;result.interest = null;}
    if (observation.intent === 'interest') {declined = false;result.interest = observation;}
  }
  if (opt_out) return {...result,classification:'suppressed',blockers:['opt_out']};
  const same = orders.filter(o => o.conversation_key === accepted[0]?.conversation_key);
  if (same.some(o => o.identity_basis === 'verified' && o.payment_status === 'paid'))
    return {...result,classification:'suppressed',blockers:['paid_order']};
  if (same.some(o => o.identity_basis === 'verified' && o.status === 'canceled'))
    return {...result,classification:'suppressed',blockers:['canceled_order']};
  if (possiblePurchase || same.some(o => o.identity_basis === 'candidate' ||
    o.identity_basis === 'verified' && o.payment_status !== 'paid'))
    result.blockers.push('purchase_or_order_requires_reconciliation');
  if (declined) return {...result,classification:'suppressed',blockers:['declined']};
  if (!lastIn) return {...result,blockers:[...result.blockers,'no_verified_inbound']};
  if (!lastOut || lastOut.at <= lastIn.at)
    return {...result,classification:'pending_service',blockers:[...result.blockers,'store_response_pending']};
  if (clock-lastIn.at >= 24*3600000) result.blockers.push('outside_service_window');
  if (!result.interest) result.blockers.push('interest_unconfirmed');
  if (!consent_verified) result.blockers.push('permission_unverified');
  if (store_open === false) result.blockers.push('store_closed');
  else if (store_open !== true) result.blockers.push('store_not_verified_open');
  for (const key of result.interest?.availability_keys ?? [])
    if (availability[key] !== 'available') result.blockers.push(`availability_unverified:${key}`);
  if (result.interest?.status !== 'resolved') result.blockers.push('product_or_variant_unresolved');
  const due = lastOut.at+follow_up_minutes*60000;
  result.due_at = new Date(due).toISOString();
  if (due > clock) result.blockers.push('not_due');
  if (recovery_contacted_at && (!Number.isFinite(Date.parse(recovery_contacted_at)) ||
    Date.parse(recovery_contacted_at) >= lastIn.at))
    result.blockers.push('already_contacted_since_reply');
  result.blockers = [...new Set(result.blockers)];
  return {...result,classification:result.blockers.length ? 'blocked' : 'shadow_candidate'};
}

// Pure shadow classifier. No IO, prices, consent mutation or delivery authority.
import { CATALOG_VERSION, CATEGORY_ITEM_KEYS, SLICES, CONES, CHOCOTONES, POPCORN_FLAVORS,
  POPCORN_SIZES, CROCANTES } from './commerce-catalog.mjs';
import { DRINKS } from './drinks-catalog.mjs';

export const RECOVERY_VERSION = 'shadow-1';
const categoryKey = {slice:CATEGORY_ITEM_KEYS.fatias,cone:CATEGORY_ITEM_KEYS.cones,
  christmas:CATEGORY_ITEM_KEYS.natal,package:CATEGORY_ITEM_KEYS.pipocas,gourmet:CATEGORY_ITEM_KEYS.pipocas};
export const normalizeInterest = value => String(value ?? '').normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const contains = (text, term) => (` ${text} `).includes(` ${normalizeInterest(term)} `);
const aliasesByKey = {slice_ninho_morango:['Ninho com Morango'],
  cascao_folheado_geleia_morango_ninho:['Folheado Geleia de Morango com Ninho']};

// Names and identifiers come from the checkout contract, never a parallel menu.
export function recoveryCatalog() {
  const simple = (group, category, variant) => Object.values(group)
    .filter(p => !p.retired).map(p => ({category, product_id:p.id,
      item_key:p.itemKey, name:p.name, variant_id:variant,
      option_id:null, aliases:aliasesByKey[p.itemKey] ?? []}));
  return [
    ...simple(SLICES, 'slice', 'fatia'),
    ...simple(CONES, 'cone', 'unidade'),
    ...simple(CHOCOTONES, 'christmas', 'porcao'),
    ...Object.values(POPCORN_FLAVORS).map(p => ({category:'gourmet',
      product_id:'pipoca-gourmet', item_key:p.itemKey, name:p.name,
      variant_id:null, option_id:p.id, aliases:[]})),
    ...Object.values(CROCANTES).map(p => ({category:'package',
      product_id:p.productId, item_key:null, name:p.name, variant_id:null,
      option_id:null, sizes:p.sizes, aliases:[]})),
    ...Object.values(DRINKS).map(p => ({category:'drink',product_id:p.id,
      item_key:p.itemKey,name:p.name,variant_id:p.variantId,option_id:null,aliases:[]})),
  ];
}

export function classifyRecoveryInterest(text, catalog = recoveryCatalog()) {
  const base = {version:RECOVERY_VERSION,catalog_version:CATALOG_VERSION,
    status:'unconfirmed',intent:'unknown',categories:[],candidates:[],
    variant_ids:[],option_ids:[],availability_keys:[],reason:'no_evidence'};
  if (typeof text !== 'string' || !text.trim() || text.length > 4096)
    return {...base,reason:'unsupported_text'};
  const t = normalizeInterest(text);
  if (/\b(?:pare de (?:me )?mandar|nao (?:me )?(?:mande|envie)|nao quero receber|nao quero (?:mais )?(?:mensagens|contato)|remov[ae] meu|sair da lista)\b/.test(t))
    return {...base,intent:'opt_out',reason:'explicit_opt_out'};
  if (/\b(?:ja paguei|ja comprei|pagamento (?:feito|realizado)|pix (?:feito|enviado))\b/.test(t))
    return {...base,intent:'possible_purchase',reason:'purchase_statement_not_payment'};
  if (/\b(?:nao quero|nao vou querer|nao tenho interesse|nao preciso|deixa pra la|so (?:estou )?olhando|desisti|cancelar|cancela)\b/.test(t))
    return {...base,intent:'declined',reason:'negative_or_mixed_intent'};
  if (/https?:\/\/|www\./i.test(text)) return {...base,reason:'link_context_unverified'};
  if (!/\b(?:quero|queria|gostaria|tem|teria|quanto|preco|valor|comprar|pedir|pedido|disponivel|separa)\b/.test(t))
    return {...base,reason:'commercial_intent_missing'};

  const categories = [];
  if (/\b(?:cascao|cascoes|cone|cones)\b/.test(t)) categories.push('cone');
  // Chocottone also occurs in a cone name; do not override an explicit cone.
  if (/\b(?:chocotone|chocottone|natal)\b/.test(t) && !categories.includes('cone')) categories.push('christmas');
  if (/\b(?:fatia|fatias)\b/.test(t) && !categories.includes('christmas')) categories.push('slice');
  const popcorn = /\b(?:pipoca|pipocas|gourmet)\b/.test(t);
  if (popcorn) {
    if (/\b(?:pacote|pacotes|ziper)\b/.test(t) || /\bpipocas? trufadas?\b/.test(t)) categories.push('package');
    if (/\b(?:gourmet|pote|potes|500\s?ml|750\s?ml|1\s?l|1 litro)\b/.test(t)) categories.push('gourmet');
    if (!categories.some(c => c === 'package' || c === 'gourmet')) categories.push('package','gourmet');
  }
  if (/\b(?:refrigerante|refrigerantes|coca|fanta|guarana)\b/.test(t)) categories.push('drink');
  const scope = catalog.filter(p => !categories.length || categories.includes(p.category));
  let matches = scope.flatMap(p => [p.name,...(p.aliases ?? [])]
    .filter(name => contains(t,name)).map(name => ({p,term:normalizeInterest(name)})));
  // Within each category a full name wins over its nested short flavor.
  matches = matches.filter(a => !matches.some(b => a.p.category === b.p.category &&
    b.term.length > a.term.length && contains(b.term,a.term)));
  const candidates = [...new Map(matches.map(({p}) => [`${p.category}:${p.product_id}:${p.option_id}`,p])).values()];
  const foundCategories = [...new Set(candidates.map(p => p.category))];
  const result = {...base,intent:'interest',categories:categories.length ? categories : foundCategories,
    candidates:candidates.map(({sizes,aliases,...p}) => p)};
  const selectedCategory = foundCategories.length === 1 ? foundCategories[0] : null;
  if (categories.length > 1 || /\b(?:sem|troca|substitui|tirar|retira)\b/.test(t))
    return {...result,status:'ambiguous',reason:'multiple_categories_or_customization'};
  if (!selectedCategory) return {...result,status:candidates.length ? 'ambiguous' : 'unconfirmed',
    reason:candidates.length ? 'category_ambiguous' : 'product_not_identified'};
  if (selectedCategory === 'gourmet') {
    const sizes = Object.values(POPCORN_SIZES).filter(s => contains(t,s.id) ||
      contains(t,s.label) || s.id === '1l' && /\b(?:1 l|um litro)\b/.test(t));
    const option_ids = candidates.map(p => p.option_id);
    const keys = [categoryKey.gourmet,...candidates.map(p => p.item_key),...sizes.map(s => s.itemKey)];
    let remaining = ` ${t} `;
    for (const {term} of matches) remaining = remaining.replaceAll(` ${term} `,' ');
    remaining = remaining.replace(/\b(?:500|750)\s?ml\b/g,' ');
    remaining = remaining.replace(/\b(?:quero|queria|gostaria|tem|teria|quanto|preco|valor|comprar|pedir|pedido|disponivel|separa|uma?|de|do|da|com|e|ou|pipocas?|gourmet|potes?|500|750|ml|1l|1|l|litro|por|favor)\b/g,'').trim();
    const valid = !remaining && !/\bou\b/.test(t) && sizes.length === 1 && option_ids.length <= sizes[0].maxOptions;
    return {...result,status:valid ? 'resolved' : 'partial',option_ids,
      variant_ids:sizes.map(s => s.id),availability_keys:keys,
      reason:valid ? 'explicit_combination' : 'size_or_combination_unresolved'};
  }
  if (selectedCategory === 'package') {
    const variant_ids = ['p','m','g'].filter(s => contains(t,`pacote ${s}`) ||
      contains(t,`tamanho ${s}`) || contains(t,` ${s} `));
    if (variant_ids.length !== 1 || candidates.length !== 1)
      return {...result,status:'partial',variant_ids,reason:'package_or_size_unresolved'};
    const item_key = candidates[0].sizes[variant_ids[0]].itemKey;
    return {...result,status:'resolved',variant_ids,availability_keys:[categoryKey.package,item_key],
      candidates:result.candidates.map(p => ({...p,item_key,variant_id:variant_ids[0]})),reason:'explicit_package'};
  }
  if (/\b(?:500\s?ml|750\s?ml|1\s?l|1 litro|pacote [pmg]|tamanho [pmg])\b/.test(t) && selectedCategory !== 'drink')
    return {...result,status:'partial',reason:'variant_incompatible_with_product'};
  return {...result,status:candidates.length === 1 ? 'resolved' : 'ambiguous',
    variant_ids:[...new Set(candidates.map(p => p.variant_id))],
    availability_keys:[categoryKey[selectedCategory],...candidates.map(p => p.item_key)].filter(Boolean),
    reason:candidates.length === 1 ? 'explicit_product' : 'multiple_products'};
}

