// Local/pre-deployment adapter. Never wired into the active webhook by import.
// Returned text is ephemeral input to the shadow evaluator, not a storage record.
export async function normalizeSignedRecoveryWebhook(raw,{signature,appSecret,
  phoneNumberId,wabaId,receivedAt}={}) {
  const reject = reason => ({accepted:false,reason,events:[]});
  if (typeof raw !== 'string' || new TextEncoder().encode(raw).length > 131072)
    return reject('payload_invalid');
  if (typeof appSecret !== 'string' || appSecret.length < 16 ||
    !/^sha256=[a-f0-9]{64}$/i.test(signature ?? '') ||
    !/^\d+$/.test(phoneNumberId ?? '') || !/^\d+$/.test(wabaId ?? '') ||
    !Number.isFinite(Date.parse(receivedAt))) return reject('configuration_invalid');
  const key = await crypto.subtle.importKey('raw',new TextEncoder().encode(appSecret),
    {name:'HMAC',hash:'SHA-256'},false,['verify']);
  const bytes = Uint8Array.from(signature.slice(7).match(/../g),h => parseInt(h,16));
  if (!await crypto.subtle.verify('HMAC',key,bytes,new TextEncoder().encode(raw)))
    return reject('signature_invalid');
  let payload;
  try {payload = JSON.parse(raw);} catch {return reject('json_invalid');}
  if (payload?.object !== 'whatsapp_business_account' || !Array.isArray(payload.entry))
    return reject('envelope_invalid');
  const entry = payload.entry.filter(e => String(e?.id) === wabaId);
  const validated = {...payload,entry};
  const events = extractOfficialMessageEvents(validated,phoneNumberId);
  const textById = new Map();
  for (const e of entry) for (const change of (Array.isArray(e.changes) ? e.changes : [])) {
    if (change?.field !== 'messages' || String(change?.value?.metadata?.phone_number_id) !== phoneNumberId) continue;
    for (const m of (Array.isArray(change.value.messages) ? change.value.messages : [])) {
      if (m.type === 'text' && typeof m.text?.body === 'string' &&
        !m.context?.forwarded && !m.context?.frequently_forwarded && !m.context?.id)
        textById.set(m.id,m.text.body);
    }
  }
  return {accepted:true,reason:events.length ? 'observed' : 'no_supported_messages',events:events.map(e => ({
    id:e.message_id,conversation_key:`${wabaId}:${phoneNumberId}:${e.phone}`,
    direction:e.direction === 'app_echo' ? 'business_outbound' : 'inbound',
    occurred_at:e.occurred_at,received_at:receivedAt,time_basis:'provider_timestamp',
    verified:true,source:'meta',content_origin:textById.has(e.message_id) ? 'customer_text' : 'unsupported',
    text:textById.get(e.message_id) ?? null,
  }))};
}

// Parser sem texto nem midia: somente IDs, direcao, telefone e timestamp.
// Nenhum dado da mensagem privada e mantido no banco.
const object = (value) => value && typeof value === "object" && !Array.isArray(value) ? value : {};
const safePhone = (v) => typeof v === "string" && /^[+0-9]{10,20}$/.test(v.trim()) ? v.trim() : null;
const safeMessageId = (v) => typeof v === "string" && /^wamid\.[A-Za-z0-9=+/_-]{3,290}$/.test(v) ? v : null;
const safeTimestamp = (v) => {
  const n=Number(v);
  return Number.isSafeInteger(n) && n>=1700000000 && n<=4102444800
    ? new Date(n*1000).toISOString() : null;
};

export function extractOfficialMessageEvents(payload, expectedPhoneNumberId) {
  if (object(payload).object !== "whatsapp_business_account" || !expectedPhoneNumberId) return [];
  const events=[];
  for (const entry of Array.isArray(payload.entry)?payload.entry.slice(0,15):[]) {
    for (const change of Array.isArray(entry.changes)?entry.changes.slice(0,15):[]) {
      const value=object(change.value);
      if (String(object(value.metadata).phone_number_id||"") !== String(expectedPhoneNumberId)) continue;
      let messages=[];
      let direction="";
      if (change.field === "messages") {
        messages=Array.isArray(value.messages)?value.messages:[];
        direction="inbound";
      } else if (change.field === "smb_message_echoes") {
        messages=Array.isArray(value.message_echoes)?value.message_echoes:[];
        direction="app_echo";
      } else continue;
      for (const raw of messages.slice(0,100)) {
        const message=object(raw);
        const id=safeMessageId(message.id);
        const phone=safePhone(direction==="inbound"?message.from:message.to);
        const occurred_at=safeTimestamp(message.timestamp);
        if (!id || !phone || !occurred_at) continue;
        events.push({message_id:id,phone,direction,occurred_at});
      }
    }
  }
  return events.slice(0,100);
}

// Existing staff consent + matching append-only audit, never inferred from interest.
export async function recoveryPermission(client,customer,now) {
 const clock=Date.parse(now),at=Date.parse(customer.consent_at);
 if(customer.commercial_opt_out!==false || customer.consent_status==='denied')
  return {verified:false,basis:'revoked'};
 if(customer.consent_status!=='granted')return {verified:false,basis:'not_recorded'};
 if(!Number.isFinite(at)||at>clock||!customer.consent_evidence?.trim()||
    customer.consent_evidence.trim().length<8)return {verified:false,basis:'invalid_evidence'};
 if(typeof client.rpc!=='function')return {verified:false,basis:'audit_unavailable'};
 try {
  const r=await client.rpc('crm_recovery_permission_evidence',{p_customer_id:customer.id});
  return r.error || r.data!==true ? {verified:false,basis:'audit_unverified'} :
   {verified:true,basis:'staff_evidence_audited'};
 }catch{return {verified:false,basis:'audit_unavailable'};}
}

