// Reuse stock after active reservations, exactly as the public storefront does.
export async function recoveryAvailability(client,rows) {
 const availability=Object.fromEntries(rows.map(r=>[r.item_key,r.status]));
 let stock=null;
 try {const r=await client.rpc('public_crocante_inventory');if(!r.error&&Array.isArray(r.data))stock=r.data;}catch{}
 for(const key of TRUFADAS_ACTIVE_ITEM_KEYS){
  const matches=stock?.filter(r=>r.item_key===key)??[],n=matches[0]?.available;
  if(matches.length!==1||!Number.isSafeInteger(n)||n<0)availability[key]='unverified';
  else if(n===0)availability[key]='sold_out';
 }
 return availability;
}

import { classifyRecoveryInterest, recoveryCatalog, RECOVERY_VERSION } from './recovery-interest.mjs';
// Internal adapter only. No route or active webhook imports this module.
export function privateRecoveryObservations(client) {
  return {
    async capture(conversationId,event) {
      if (event?.verified !== true || event.direction !== 'inbound' ||
        event.time_basis !== 'provider_timestamp' ||
        event.content_origin !== 'customer_text' || event.conversation_key !== conversationId)
        return {stored:false,reason:'unverified_observation'};
      const semantic = classifyRecoveryInterest(event.text);
      const r = await client.rpc('crm_recovery_store_observation',{
        p_conversation_id:conversationId,p_message_id:event.id,p_occurred_at:event.occurred_at,p_semantic:semantic});
      if (r.error) throw new Error('private_observation_write_failed');
      return {stored:r.data === true,reason:r.data === true ? 'stored' : 'duplicate'};
    },
    async read(conversationId) {
      const r = await client.rpc('crm_recovery_read_observations',{p_conversation_id:conversationId});
      if (r.error || !Array.isArray(r.data) || r.data.length>1000) throw new Error('private_observation_read_failed');
      const catalog = recoveryCatalog();
      for (const row of r.data) {
        const s = row.semantic;
        if (s?.version !== RECOVERY_VERSION || !Array.isArray(s.candidates) ||
          s.candidates.some(p => !catalog.some(c => c.product_id===p.product_id && c.category===p.category && c.option_id===p.option_id)))
          throw new Error('private_observation_version_invalid');
      }
      return r.data;
    },
  };
}

// Shared Web Crypto protocol. Contains no project/admin key or customer data.
export const SCHEDULER_ACTION='reevaluate_due_shadow';
export const SCHEDULER_PATH='/functions/v1/crm-recovery-reevaluate';
const encoder=new TextEncoder();
export function schedulerTarget(projectUrl){
 const u=new URL(projectUrl);
 if(u.protocol!=='https:'||!/^[a-z0-9]{20}\.supabase\.co$/.test(u.hostname)||u.port||
  u.username||u.password||u.search||u.hash||!['','/'].includes(u.pathname))throw Error('scheduler_configuration_invalid');
 return u.origin+SCHEDULER_PATH;
}
// Classification only; JWT cryptographic verification remains in the gateway.
// Reject accidental use of service/admin credentials, including legacy JWTs.
export function publicGatewayKey(key){
 if(typeof key!=='string')return false;
 if(/^sb_publishable_[A-Za-z0-9_-]{12,220}$/.test(key))return true;
 try{
  const parts=key.split('.');if(parts.length!==3||key.length>1800)return false;
  const claims=JSON.parse(atob(parts[1].replace(/-/g,'+').replace(/_/g,'/')));
  return claims.role==='anon';
 }catch{return false;}
}
function keyBytes(secret){
 if(typeof secret!=='string'||!/^[A-Za-z0-9_-]{43}$/.test(secret))throw Error('scheduler_configuration_invalid');
 const bytes=Uint8Array.from(atob(secret.replace(/-/g,'+').replace(/_/g,'/')+'='),c=>c.charCodeAt(0));
 if(bytes.length!==32)throw Error('scheduler_configuration_invalid');return bytes;
}
const message=(target,timestamp,nonce,raw)=>encoder.encode(`recovery-scheduler-v1\nPOST\n${target}\n${timestamp}\n${nonce}\n${raw}`);
export async function boundedText(stream,max=512,timeoutMs=5000){
 if(!stream)return '';
 const reader=stream.getReader(),chunks=[];let size=0,timer;
 const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('body_timeout')),timeoutMs);});
 try{
  while(true){const {done,value}=await Promise.race([reader.read(),timeout]);if(done)break;size+=value.byteLength;
   if(size>max){await reader.cancel();throw Error('body_too_large');}chunks.push(value);}
  const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}
  return new TextDecoder('utf-8',{fatal:true}).decode(bytes);
 }catch(error){await reader.cancel().catch(()=>{});throw error;}
 finally{clearTimeout(timer);reader.releaseLock();}
}
export async function signSchedulerRequest({projectUrl,gatewayKey,secret,now=Date.now(),scheduledAt,nonce=crypto.randomUUID()}){
 const target=schedulerTarget(projectUrl);
 if(!publicGatewayKey(gatewayKey)||!Number.isSafeInteger(now)||!Number.isSafeInteger(scheduledAt)||
  scheduledAt%300!==0||!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(nonce))throw Error('scheduler_configuration_invalid');
 const timestamp=String(Math.floor(now/1000));
 const raw=JSON.stringify({v:1,action:SCHEDULER_ACTION,scheduled_at:scheduledAt});
 const key=await crypto.subtle.importKey('raw',keyBytes(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);
 const signature=Array.from(new Uint8Array(await crypto.subtle.sign('HMAC',key,message(target,timestamp,nonce,raw))),b=>b.toString(16).padStart(2,'0')).join('');
