  if(!/^\d{10}$/.test(timestamp)||!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(nonce)||
   !/^[a-f0-9]{64}$/.test(signature)||Number(timestamp)*1000<now-90000||Number(timestamp)*1000>now+30000)return {ok:false};
